// Mapping table for Thai Private Use Area (PUA) characters generated by Acrobat PDFMaker
const thaiPua = {
  0xF700: 0x0E48, 0xF701: 0x0E49, 0xF702: 0x0E4A, 0xF703: 0x0E4B, 0xF704: 0x0E4C,
  0xF705: 0x0E48, 0xF706: 0x0E49, 0xF707: 0x0E4A, 0xF708: 0x0E4B, 0xF709: 0x0E4C,
  0xF70A: 0x0E48, 0xF70B: 0x0E49, 0xF70C: 0x0E4A, 0xF70D: 0x0E4B, 0xF70E: 0x0E4C,
  0xF70F: 0x0E34, 0xF710: 0x0E35, 0xF711: 0x0E36, 0xF712: 0x0E37, 0xF713: 0x0E31,
  0xF718: 0x0E38, 0xF719: 0x0E39, 0xF71A: 0x0E3A
};

function fixThaiPua(str) {
  let out = '';
  for (let i = 0; i < str.length; i++) {
    const code = str.charCodeAt(i);
    out += thaiPua[code] ? String.fromCharCode(thaiPua[code]) : str[i];
  }
  return out.replace(/\u0e4d\u0e32/g, '\u0e33') // nikhahit + sara aa -> sara am
            .replace(/ปีญญา/g, 'ปัญญา')
            .replace(/ป้ันสกุล/g, 'ปิ่นสกุล')
            .replace(/ป้ยะพัชร์/g, 'ปิยะพัชร์')
            .replace(/ชุมแวงวาป๊/g, 'ชุมแวงวาปี')
            .replace(/จํารัสธนสาร/g, 'จำรัสธนสาร')
            .replace(/อาจารยวราวุธ/g, 'อาจารย์วราวุธ')
            .replace(/อาจารอนุชิดา/g, 'อาจารย์อนุชิดา')
            .replace(/อาจาร์/g, 'อาจารย์')
            .replace(/ห๊องสมุด/g, 'ห้องสมุด')
            .replace(/อีสานใต๊/g, 'อีสานใต้')
            .replace(/สระว้ายน้ำ/g, 'สระว่ายน้ำ')
            .replace(/ไฟฟ่า/g, 'ไฟฟ้า');
}

const manualAliases = {
  'ผู้ช่วยศาสตราจารย์สิทธิศักดิ์ พงธรรมินทร์': '500107', // ผศ.สิทธิศักดิ์ พงผือฮี (พงธรรมินทร์)
  'ผู้ช่วยศาสาตราจารย์ ดร.ศรัณย์ จำรัสธนสาร': '900222', // ผศ.ดร.ศรัณย์ จำรัสธนสาร
  'อาจารย์ป้ติวรรณ ฝ้ายโคกสูง': '900116',               // อ.ปิติวรรณ ฝ้ายโคกสูง
  'อาจารย์ปิติวรรณ ฝ้ายโคกสูง': '900116',
  'ผศ.ดร.ปรีชา ชุมแวงวาปี': '900188',                 // ผศ.ดร.ปรัชญา ชุมแวงวาปี
};

function cleanTitle(raw) {
  return raw
    .replace(/^(ผู้ช่วยศาสตราจารย์|ผูชวยศาสตราจารย|ผู้ช่วยศาสาตราจารย์|รองศาสตราจารย์|รองศาสตราจารย|ผศ\.|รศ\.|อาจารย์|อาจารย|อาจาร|อาจาร์|อ\.|ดร\.|นางสาว|นาง|นาย)\s*/g, '')
    .replace(/^(ดร\.|ผู้ช่วยศาสตราจารย์|ผู้ช่วยศาสาตราจารย์|ผศ\.|รองศาสตราจารย์|รศ\.)\s*/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// 8 specific facilities/labs to be SKIPPED per user request
const SKIPPED_BUILDING_KEYWORDS = [
  'สำนักงานคณบดีคณะครุศาสตร์',
  'เทคโนโลยีวิศวกรรมโยธา',
  'วิศวกรรมการจัดการอุตสาหกรรม',
  'ศิลปะและการออกแบบ',
  'สถาปัตยกรรม - เทคโนโลยีไฟฟ้า',
  'กองอาคารสถานที่และบริการ',
  'BRU DOME',
  'โรงจอดรถงานยานพาหนะ'
];

function isSkippedBuilding(header) {
  return SKIPPED_BUILDING_KEYWORDS.some(k => header.includes(k));
}

// Mapping rule from PDF building header to Building Code in Database
function getBuildingCode(header) {
  const h = header.replace(/\s+/g, ' ');
  if (h.includes('อาคาร 1') && !h.includes('อาคาร 10') && !h.includes('อาคาร 12') && !h.includes('อาคาร 13') && !h.includes('อาคาร 14') && !h.includes('อาคาร 15') && !h.includes('อาคาร 16') && !h.includes('อาคาร 17') && !h.includes('อาคาร 18') && !h.includes('อาคาร 19')) return 'B01';
  if (h.includes('อาคาร 2') && !h.includes('อาคาร 20') && !h.includes('อาคาร 21') && !h.includes('อาคาร 22') && !h.includes('อาคาร 23') && !h.includes('อาคาร 24') && !h.includes('อาคาร 25') && !h.includes('อาคาร 26') && !h.includes('อาคาร 27')) return 'B02';
  if (h.includes('อาคาร 5') && !h.includes('15') && !h.includes('25') && !h.includes('50')) return 'B05';
  if (h.includes('อาคาร 6') && !h.includes('16') && !h.includes('26')) return 'B06';
  if (h.includes('อาคาร 7') && !h.includes('17') && !h.includes('27')) return 'B07';
  if (h.includes('อาคาร 10')) return 'B10';
  if (h.includes('อาคาร 12')) return 'B12';
  if (h.includes('อาคาร 13')) return 'B13';
  if (h.includes('อาคาร 14')) return 'B14';
  if (h.includes('15')) return 'B15';
  if (h.includes('อาคาร 16')) return 'B16';
  if (h.includes('17') || h.includes('นวัตปัญญา')) return 'B17';
  if (h.includes('อาคาร 18')) return 'B18';
  if (h.includes('อาคาร 19')) return 'B19';
  if (h.includes('20') || h.includes('สิริวิทยเกษตร')) return 'B20';
  if (h.includes('อาคาร 21')) return 'B21';
  if (h.includes('อาคาร 22')) return 'B22';
  if (h.includes('23') || h.includes('Complex') || h.includes('อเนกคุณาคาร')) return 'B23';
  if (h.includes('อาคาร 24')) return 'B24';
  if (h.includes('อาคาร 25')) return 'B25';
  if (h.includes('อาคาร 26')) return 'B26';
  if (h.includes('27') || h.includes('โรงเรียนสาธิต')) return 'B27';
  if (h.includes('IT')) return 'B-IT';
  if (h.includes('เซรามิกส์')) return 'B-CER';
  if (h.includes('บรรณราชนครินทร์') || h.includes('ห้องสมุด')) return 'B-LIB';
  if (h.includes('ศูนย์วัฒนธรรมอีสานใต้')) return 'B-CUL';
  if (h.includes('มาลิณีจุโฑปะมา')) return 'B-AUD2';
  if (h.includes('วิชชาอัตศาสตร์')) return 'B-AUD1';
  if (h.includes('โรงยิมส์')) return 'B-GYM';
  if (h.includes('ชลาธาร') || h.includes('สระว่ายน้ำ')) return 'POOL';
  return null;
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function fetchSsoUser(rawName) {
  if (manualAliases[rawName]) {
    const url = baseUrl + '/api/users?search=' + encodeURIComponent(manualAliases[rawName]);
    const res = await fetch(url, { headers: { 'X-API-Key': apiKey } });
    const json = await res.json();
    if (json.data && json.data.length > 0) return json.data[0];
  }

  const cleaned = cleanTitle(rawName);
  const parts = cleaned.split(' ');
  const firstName = parts[0];
  const lastName = parts[parts.length - 1];

  let query = lastName && lastName.length > 2 ? lastName : firstName;
  let url = baseUrl + '/api/users?search=' + encodeURIComponent(query);
  try {
    let res = await fetch(url, { headers: { 'X-API-Key': apiKey } });
    let json = await res.json();
    let matches = json.data || [];

    let exact = matches.find(m => {
      const ssoClean = cleanTitle(m.full_name);
      return ssoClean.includes(firstName) && (parts.length === 1 || ssoClean.includes(lastName));
    });

    if (!exact && parts.length > 1) {
      await sleep(100);
      url = baseUrl + '/api/users?search=' + encodeURIComponent(firstName);
      res = await fetch(url, { headers: { 'X-API-Key': apiKey } });
      json = await res.json();
      matches = json.data || [];
      exact = matches.find(m => {
        const ssoClean = cleanTitle(m.full_name);
        return ssoClean.includes(firstName) && ssoClean.includes(lastName);
      });
    }

    return exact || null;
  } catch (err) {
    console.warn(`SSO query failed for ${rawName}:`, err.message);
    return null;
  }
}

async function main() {
  const isDryRun = process.argv.includes('--dry-run');
  console.log(`=== BRU Building Auditor Import (${isDryRun ? 'DRY RUN' : 'LIVE EXECUTION'}) ===`);

  const pdfTextRaw = fs.readFileSync('C:/Users/Chartwut/.gemini/antigravity/brain/de6ad965-b40b-4cbe-9288-bd6ef0b1a3aa/pdf_extracted.txt', 'utf8');
  const pdfText = fixThaiPua(pdfTextRaw);
  const lines = pdfText.split('\n').map(l => l.replace(/\s+/g, ' ').trim()).filter(l => l && !l.startsWith('--- PAGE '));

  const sections = [];
  let currHeader = null;
  let currMembers = [];

  for (const l of lines) {
    if (l.includes('คณะกรรมการ')) {
      if (currHeader) {
        sections.push({ header: currHeader, members: currMembers });
      }
      currHeader = l;
      currMembers = [];
    } else {
      if (currHeader) {
        currMembers.push(l);
      }
    }
  }
  if (currHeader) {
    sections.push({ header: currHeader, members: currMembers });
  }

  console.log(`Parsed ${sections.length} building sections from PDF.`);

  const skippedList = [];
  const confidentList = [];

  for (const s of sections) {
    if (isSkippedBuilding(s.header)) {
      skippedList.push(s);
    } else {
      const code = getBuildingCode(s.header);
      if (code) {
        confidentList.push({ ...s, code });
      } else {
        skippedList.push(s);
      }
    }
  }

  console.log(`Confident Buildings to Import: ${confidentList.length}`);
  console.log(`Skipped Specific Facilities to Report Separately: ${skippedList.length}`);

  // Fetch all DB buildings
  const dbBuildings = await prisma.building.findMany();
  const dbBuildingMap = new Map(); // code -> building
  for (const b of dbBuildings) {
    dbBuildingMap.set(b.code, b);
  }

  // Collect unique members from confident list
  const memberNameMap = new Map(); // rawName -> { raw, clean, ssoUser, dbUser }
  for (const item of confidentList) {
    for (const m of item.members) {
      if (!memberNameMap.has(m)) {
        memberNameMap.set(m, { raw: m, clean: cleanTitle(m) });
      }
    }
  }

  console.log(`\nResolving ${memberNameMap.size} unique committee members via BRU SSO API & DB...`);

  // Existing DB users
  const dbUsers = await prisma.user.findMany();
  const dbUserByLogin = new Map();
  const dbUserByName = new Map();
  for (const u of dbUsers) {
    dbUserByLogin.set(u.userlogin.toLowerCase(), u);
    dbUserByName.set(cleanTitle(u.fullName), u);
  }

  for (const [rawName, info] of memberNameMap.entries()) {
    // 1. Check if user already exists in DB by clean name
    const existingDb = dbUserByName.get(info.clean);
    if (existingDb) {
      info.dbUser = existingDb;
      info.userlogin = existingDb.userlogin;
      info.fullName = existingDb.fullName;
      info.source = 'EXISTING_DB';
      continue;
    }

    // 2. Fetch from BRU SSO
    await sleep(80);
    const sso = await fetchSsoUser(rawName);
    if (sso) {
      info.ssoUser = sso;
      info.userlogin = sso.userlogin;
      info.fullName = sso.full_name.replace(/\s+/g, ' ').trim();
      info.positionName = sso.position_name || 'กรรมการตรวจประเมินอาคาร';
      info.departmentId = sso.departmentid || null;
      info.email = sso.email || (sso.userlogin ? `${sso.userlogin}@bru.ac.th` : null);
      info.source = 'SSO_API';
    } else {
      // 3. Fallback
      info.userlogin = 'auditor_' + Math.abs(info.clean.split('').reduce((a, b) => ((a << 5) - a) + b.charCodeAt(0), 0)).toString(36);
      info.fullName = rawName;
      info.positionName = 'กรรมการตรวจประเมินอาคาร';
      info.source = 'LOCAL_FALLBACK';
      console.warn(`[NO SSO MATCH] ${rawName} -> Fallback login: ${info.userlogin}`);
    }
  }

  console.log(`\nAll ${memberNameMap.size} members resolved!`);

  if (!isDryRun) {
    // 1. Upsert users into PostgreSQL
    console.log('\n--- Upserting Committee Members into PostgreSQL User Table ---');
    for (const [rawName, info] of memberNameMap.entries()) {
      const user = await prisma.user.upsert({
        where: { userlogin: info.userlogin },
        update: {
          role: 'AUDITOR',
          fullName: info.fullName,
          positionName: info.positionName || undefined,
          departmentId: info.departmentId || undefined,
          email: info.email || undefined
        },
        create: {
          userlogin: info.userlogin,
          fullName: info.fullName,
          role: 'AUDITOR',
          positionName: info.positionName || 'กรรมการตรวจประเมินอาคาร',
          departmentId: info.departmentId || null,
          email: info.email || null
        }
      });
      info.dbUser = user;
    }

    // 2. Build BuildingAuditorsMap
    console.log('\n--- Building and Saving building_auditors Map ---');
    const buildingAuditorsMap = {};

    for (const item of confidentList) {
      const bRec = dbBuildingMap.get(item.code);
      if (!bRec) {
        console.error(`ERROR: Building ${item.code} not found in DB!`);
        continue;
      }

      const assignedList = [];
      const seen = new Set();
      for (const m of item.members) {
        const info = memberNameMap.get(m);
        if (!info || !info.dbUser) continue;
        const key = info.dbUser.id;
        if (seen.has(key)) continue;
        seen.add(key);

        assignedList.push({
          userId: info.dbUser.id,
          userlogin: info.dbUser.userlogin,
          fullName: info.dbUser.fullName
        });
      }

      buildingAuditorsMap[bRec.id] = assignedList;
      console.log(`✓ [${bRec.code}] ${bRec.name}: Assigned ${assignedList.length} auditors.`);
    }

    // Save into SystemSetting
    await prisma.systemSetting.upsert({
      where: { key: 'building_auditors' },
      update: { value: JSON.stringify(buildingAuditorsMap) },
      create: { key: 'building_auditors', value: JSON.stringify(buildingAuditorsMap) }
    });

    console.log(`\n🎉 Successfully saved building_auditors for ${Object.keys(buildingAuditorsMap).length} buildings into SystemSetting!`);
  }

  // Generate Report for Skipped Buildings
  const reportPath = 'C:/Users/Chartwut/.gemini/antigravity/brain/de6ad965-b40b-4cbe-9288-bd6ef0b1a3aa/skipped_facilities_report.json';
  fs.writeFileSync(reportPath, JSON.stringify(skippedList, null, 2), 'utf8');
  console.log(`\nSaved skipped facilities data to ${reportPath}`);
}

main().catch(console.error).finally(() => prisma['$disconnect'] && prisma['$disconnect']());
